/// A recognized leading honorific, retained in source order.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum PersonTitle {
    /// The `mr` honorific.
    Mr,
    /// The `mrs` honorific.
    Mrs,
    /// The `ms` honorific.
    Ms,
    /// The `miss` honorific.
    Miss,
    /// The `mx` honorific.
    Mx,
    /// The `dr` honorific.
    Dr,
    /// The `prof` honorific.
    Prof,
    /// The `professor` honorific.
    Professor,
    /// The `sir` honorific.
    Sir,
    /// The `dame` honorific.
    Dame,
    /// The `lord` honorific.
    Lord,
    /// The `lady` honorific.
    Lady,
    /// The `rev` honorific.
    Rev,
    /// The `reverend` honorific.
    Reverend,
    /// The `rt` honorific.
    Rt,
    /// The `hon` honorific.
    Hon,
}

impl PersonTitle {
    fn from_token(token: &str) -> Option<Self> {
        match token {
            "mr" => Some(Self::Mr),
            "mrs" => Some(Self::Mrs),
            "ms" => Some(Self::Ms),
            "miss" => Some(Self::Miss),
            "mx" => Some(Self::Mx),
            "dr" => Some(Self::Dr),
            "prof" => Some(Self::Prof),
            "professor" => Some(Self::Professor),
            "sir" => Some(Self::Sir),
            "dame" => Some(Self::Dame),
            "lord" => Some(Self::Lord),
            "lady" => Some(Self::Lady),
            "rev" => Some(Self::Rev),
            "reverend" => Some(Self::Reverend),
            "rt" => Some(Self::Rt),
            "hon" => Some(Self::Hon),
            _ => None,
        }
    }
}

struct ParsedPersonName {
    titles: Vec<PersonTitle>,
    normalized: Option<String>,
    core: String,
}

impl ParsedPersonName {
    fn parse(name: &str) -> Self {
        let mut titles = Vec::new();
        let mut remainder = name;
        while let Some(word) = remainder.split_whitespace().next() {
            let Some(title) = PersonTitle::from_token(word.strip_suffix('.').unwrap_or(word))
            else {
                break;
            };
            titles.push(title);
            remainder = remainder[word.len()..].trim_start();
        }
        let normalized = if !titles.is_empty() {
            unwrap_given_name(remainder).unwrap_or_else(|| remainder.to_owned())
        } else {
            remainder.to_owned()
        };
        // Legacy comparison features strip punctuation before recognizing titles.
        // Keep that ordering: e.g. `(Mr) Smith` and `Mr, Smith` already lose `mr`.
        let tokenized = tokens(name);
        let core = tokenized
            .split_whitespace()
            .skip_while(|word| PersonTitle::from_token(word).is_some())
            .collect::<Vec<_>>()
            .join(" ");
        Self {
            titles,
            normalized: (!normalized.is_empty()).then_some(normalized),
            core,
        }
    }
}

fn unwrap_given_name(name: &str) -> Option<String> {
    let (given, surname) = name.strip_prefix('(')?.split_once(')')?;
    // A closing group must be followed by a separate, nonempty name sequence.
    if !surname.starts_with(char::is_whitespace) {
        return None;
    }
    let surname = surname.trim();
    let name_like = |value: &str| {
        !value.is_empty()
            && value.split_whitespace().all(|word| {
                !matches!(
                    word,
                    "and" | "or" | "trading" | "as" | "trustee" | "ceo" | "director"
                ) && word.chars().next().is_some_and(char::is_alphabetic)
                    && word.chars().last().is_some_and(char::is_alphabetic)
                    && word.chars().all(|c| {
                        c.is_alphabetic()
                            || is_combining_mark(c)
                            || matches!(c, '-' | '\'' | '’' | '‘' | 'ʼ')
                    })
            })
    };
    (name_like(given) && name_like(surname)).then(|| format!("{given} {surname}"))
}

